--left is used to calculate left line drag. lineLeftDrag = maxLeft - firstLetterLeft
--font middle size is 1/2 for the base font. gotta test for other fonts
--right is the amount a letter pushes the next letter away
--kerning is the amount the rightsided character is drawn towards the left sided character

--distance towards next letter =
---- (('size'+'letter'.'code'.'right'+
--------'letter'.'nextCode'.'left'-'letter'.'code'.'kerning'.'nextCode')
--------*fontSize)+'between'

